-- CS-103 source package 1.0.0; database revision 1.
-- Run ONLY this file in the existing project's SQL Editor as postgres.
-- Imports an unpublished draft. No release, assignment, schema or scoring changes.
-- An identical rerun is a no-op, including after publication/assignment.
-- Different content under these identifiers aborts instead of overwriting records.
begin;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "f03c1354-7aec-596c-b72e-7df51d92be50", "slug": "cs-103-helping-customers-when-you-don-t-know-the-answer", "version": 1, "title": "Helping Customers When You Don't Know the Answer", "description": "Learn how to respond with confidence when a customer asks an unfamiliar question. Gather details, verify information, and make a helpful handoff.", "category": "Customer Experience & Sales", "passing_percent": 80}, "lessons": [{"id": "18a678d9-7c59-54d0-9393-c5c7088056e4", "position": 1, "title": "Stay Calm and Take Ownership", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers expect help. They do not expect every new employee to know everything."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Be honest and helpful"}, {"type": "paragraph", "text": "Say you want to verify the answer. Keep a calm tone. Avoid guessing or dismissing the customer."}, {"type": "heading", "text": "Own the next step"}, {"type": "paragraph", "text": "Explain what you will do next. You might check a label, consult a coworker, or find official instructions."}, {"type": "heading", "text": "Stay connected"}, {"type": "paragraph", "text": "Do not send a customer away without a clear handoff. If you must leave, explain where you are going and return as promised."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks whether a certain blade fits their saw. You are unsure. You say you will check the saw model and blade information before giving an answer."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “I want to make sure we get this right.”"}, {"type": "bullet", "text": "Ask for the product model or package."}, {"type": "bullet", "text": "Explain the next step."}, {"type": "bullet", "text": "Return with an answer or a clear referral."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Guessing to sound confident."}, {"type": "bullet", "text": "Saying “I don’t know” and walking away."}, {"type": "bullet", "text": "Promising an answer you cannot verify."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a specialist when product compatibility or safe use is uncertain. Never recommend an unverified blade or accessory."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Be honest."}, {"type": "bullet", "text": "Take responsibility for the next step."}, {"type": "bullet", "text": "Keep the customer informed."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P01"}, {"type": "paragraph", "text": "Question: You do not know whether a blade fits a saw. What should you say?"}, {"type": "bullet", "text": "A. “It probably fits.”"}, {"type": "bullet", "text": "B. “I’m new. Ask someone else.”"}, {"type": "bullet", "text": "C. “Let’s check the model and the blade specifications.”"}, {"type": "bullet", "text": "D. “All blades fit most saws.”"}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: Checking the model and specifications is a useful next step. It avoids guessing."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "d48ff8f2-2c8c-5af4-bbb5-baf70dc90451", "position": 2, "title": "Ask Questions That Find the Missing Detail", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Many questions are hard to answer because key details are missing."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Clarify the problem"}, {"type": "paragraph", "text": "Ask what the customer is trying to do. Find out what is not working or what needs replacing."}, {"type": "heading", "text": "Identify the product"}, {"type": "paragraph", "text": "Ask for a model number, measurements, old part, package, or photo. Do not assume similar-looking parts are interchangeable."}, {"type": "heading", "text": "Repeat the request"}, {"type": "paragraph", "text": "Summarize what you know. This helps the customer correct missing or misunderstood details."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a replacement filter but does not know the size. You ask for the equipment model and the label on the old filter. You can now look for a verified match."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask: “What equipment is this for?”"}, {"type": "bullet", "text": "Ask: “Do you have the model number?”"}, {"type": "bullet", "text": "Ask: “Can you show me the old part or a photo?”"}, {"type": "bullet", "text": "Repeat the key details."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Searching without enough information."}, {"type": "bullet", "text": "Assuming size from appearance."}, {"type": "bullet", "text": "Asking for details unrelated to the problem."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker for help identifying a model or part. Use manufacturer documentation for compatibility."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Find the missing detail."}, {"type": "bullet", "text": "Use product identifiers."}, {"type": "bullet", "text": "Confirm what you heard."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P02"}, {"type": "paragraph", "text": "Question: A customer needs a filter but does not know the size. What detail would help most?"}, {"type": "bullet", "text": "A. Their favorite brand color."}, {"type": "bullet", "text": "B. The equipment model or old filter label."}, {"type": "bullet", "text": "C. The date of their last store visit."}, {"type": "bullet", "text": "D. Their preferred checkout lane."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: A model or filter label can help verify compatibility."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "4d4c10ab-60e0-50e8-8ed5-47cd0762a042", "position": 3, "title": "Use Reliable Information", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A confident guess can lead to a wrong purchase or unsafe use."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with the product"}, {"type": "paragraph", "text": "Read the package and labels. Look for model numbers, sizes, ratings, and warnings. Do not treat packaging as a substitute for full instructions when more detail is needed."}, {"type": "heading", "text": "Use official instructions"}, {"type": "paragraph", "text": "For compatibility, safety, and warranty questions, prefer current manufacturer information. Check that the document matches the exact model."}, {"type": "heading", "text": "Know what is not confirmed"}, {"type": "paragraph", "text": "If you cannot verify a claim, tell the customer. Explain the next safe step."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks whether a particular battery works with a power tool. You compare the exact tool and battery models using official compatibility information. You do not rely on color or appearance."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “Let’s check the model information.”"}, {"type": "bullet", "text": "Read the label with the customer."}, {"type": "bullet", "text": "Use current official product instructions when available."}, {"type": "bullet", "text": "State clearly what remains unverified."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Relying on memory for a safety claim."}, {"type": "bullet", "text": "Using instructions for a different model."}, {"type": "bullet", "text": "Treating an online comment as a manufacturer policy."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a specialist or manager if official information is unavailable or unclear. Refer the customer to manufacturer support or a qualified professional when appropriate."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Check exact models."}, {"type": "bullet", "text": "Prefer official instructions."}, {"type": "bullet", "text": "Do not present guesses as facts."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P03"}, {"type": "paragraph", "text": "Question: A customer asks whether a battery fits a tool. Which source is strongest?"}, {"type": "bullet", "text": "A. A guess based on the color."}, {"type": "bullet", "text": "B. A comment from an unknown forum."}, {"type": "bullet", "text": "C. Current manufacturer compatibility information for the exact models."}, {"type": "bullet", "text": "D. A similar product on the next shelf."}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: Official information for the exact models is more reliable than appearance or guesses."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "b8150481-d144-5939-ad60-0077bede9229", "position": 4, "title": "Make a Helpful Handoff", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A customer should not need to repeat the same story several times."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Choose the right helper"}, {"type": "paragraph", "text": "Find a coworker with relevant product knowledge. Use a manager for store policy or an unresolved service issue."}, {"type": "heading", "text": "Summarize the need"}, {"type": "paragraph", "text": "Tell the next employee what the customer wants, what details you checked, and what remains unanswered."}, {"type": "heading", "text": "Follow through"}, {"type": "paragraph", "text": "Confirm that the handoff happened. If no one is available, explain the options without promising a time you cannot guarantee."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a part for a pressure washer. You have the model number but cannot confirm the fitting. You introduce the customer to the power equipment specialist and share the model number and the question."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “I have the model number. Let me bring in our equipment specialist.”"}, {"type": "bullet", "text": "Share the details already collected."}, {"type": "bullet", "text": "Confirm the customer knows who will help next."}, {"type": "bullet", "text": "Avoid promising a wait time without checking."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Pointing vaguely across the store."}, {"type": "bullet", "text": "Making the customer repeat every detail."}, {"type": "bullet", "text": "Leaving before confirming the handoff."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager when a specialist is unavailable or a customer needs a policy decision. Refer technical work beyond retail advice to a qualified professional."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Find the right helper."}, {"type": "bullet", "text": "Share the details."}, {"type": "bullet", "text": "Confirm the handoff."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P04"}, {"type": "paragraph", "text": "Question: You need to transfer a customer to a plumbing specialist. What should you do?"}, {"type": "bullet", "text": "A. Tell the customer to find someone in plumbing."}, {"type": "bullet", "text": "B. Introduce the specialist and share the details you already gathered."}, {"type": "bullet", "text": "C. Walk away without explanation."}, {"type": "bullet", "text": "D. Give an answer you are unsure about."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: A good handoff saves time and shows ownership of the customer’s need."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "85049f8d-ff8b-58db-8b3a-ff95c751dffc", "position": 5, "title": "Know When to Stop and Escalate", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Some questions involve risks or decisions outside a retail employee’s authority."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Recognize higher-risk topics"}, {"type": "paragraph", "text": "Electrical wiring, gas connections, structural loads, chemical mixing, and power equipment safety can involve serious hazards. Product advice is not a substitute for professional work."}, {"type": "heading", "text": "Separate product facts from professional advice"}, {"type": "paragraph", "text": "You may help locate a product or find official instructions. Do not design, approve, or certify work that requires a qualified professional."}, {"type": "heading", "text": "Escalate clearly"}, {"type": "paragraph", "text": "Explain why you need another source. Ask a manager for store policies. Use official manufacturer support for unresolved product questions. Recommend a qualified professional for work beyond your role."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks you to confirm that a fastener will support a heavy overhead load. You can help find product specifications. You do not approve the installation. You explain that the load and installation need qualified evaluation."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “I can help find the product specifications.”"}, {"type": "bullet", "text": "Say: “I cannot confirm this installation is safe.”"}, {"type": "bullet", "text": "Refer to a qualified professional for technical approval."}, {"type": "bullet", "text": "Ask a manager about store policy."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating a package rating as approval for every installation."}, {"type": "bullet", "text": "Giving installation advice outside your training."}, {"type": "bullet", "text": "Ignoring a warning because a customer wants a quick answer."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate immediately when there is a safety concern, an unclear manufacturer warning, or a request for technical approval outside retail scope."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Know your role limits."}, {"type": "bullet", "text": "Escalate safety-sensitive questions."}, {"type": "bullet", "text": "Give a clear next step."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P05"}, {"type": "paragraph", "text": "Question: A customer asks you to approve hardware for a heavy overhead installation. What should you do?"}, {"type": "bullet", "text": "A. Guarantee the hardware is safe."}, {"type": "bullet", "text": "B. Recommend the biggest fastener."}, {"type": "bullet", "text": "C. Find product specifications and refer the installation decision to a qualified professional."}, {"type": "bullet", "text": "D. Tell the customer any fastener will work."}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: Retail employees can provide verified product facts. They should not certify a high-risk installation."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}], "questions": [{"id": "5249089e-04c8-5601-a024-60ba50a3eb02", "position": 1, "prompt": "A customer asks a question about a product you have never sold. What should you do first?", "options": ["Guess based on the product name.", "Say you will verify the information and explain the next step.", "Tell them to shop elsewhere.", "Promise the product will work."], "correct_option": 1, "explanation": "Honesty and a clear next step build trust. Guessing or dismissing the customer does not help."}, {"id": "0a298efa-6926-54c3-9bd5-fcdec56161ae", "position": 2, "prompt": "A customer needs a replacement part for a tool. Which information is most useful?", "options": ["The tool model number and old part details.", "The customer’s preferred payment method.", "The color of the store sign.", "The day the customer usually shops."], "correct_option": 0, "explanation": "Exact model and part details support a reliable match. The other details do not identify the part."}, {"id": "b55e5a83-947b-5570-b6b1-14c031120785", "position": 3, "prompt": "A customer asks about a tool battery’s compatibility. What is the best next step?", "options": ["Choose one with the same color.", "Use a different tool’s manual.", "Ask another customer to guess.", "Check current manufacturer information for the exact tool and battery models."], "correct_option": 3, "explanation": "Manufacturer compatibility information for exact models is the appropriate source. Appearance and unrelated manuals are not reliable."}, {"id": "fbfad3d3-5ad6-5199-bbce-9e45c2559bbd", "position": 4, "prompt": "You have collected a pressure washer model number but need help finding a fitting. How should you hand off the customer?", "options": ["Point toward the equipment counter.", "Tell them to start the story over.", "Introduce a specialist and share the model and unanswered question.", "Leave without confirming anyone is available."], "correct_option": 2, "explanation": "A direct handoff with the known details saves time and keeps the customer supported."}, {"id": "3c56a04b-4055-5c6b-b145-e74c8f172d81", "position": 5, "prompt": "A customer asks you to approve a fastener for a heavy overhead load. What is the best response?", "options": ["Promise it is safe if the package shows a high rating.", "Help locate specifications and refer the installation decision to a qualified professional.", "Recommend any larger fastener.", "Say you can certify the installation."], "correct_option": 1, "explanation": "Product ratings do not establish suitability for every installation. A qualified professional must evaluate the application."}], "catalog": {"course_code": "CS-103", "skill_level": "foundations", "topics": ["Helping Customers When You Don't Know the Answer"], "keywords": ["Stay Calm and Take Ownership", "Ask Questions That Find the Missing Detail", "Use Reliable Information", "Make a Helpful Handoff", "Know When to Stop and Escalate", "Why this matters", "Lesson content", "Be honest and helpful", "Own the next step", "Stay connected", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Unscored lesson practice", "Optional practice", "Clarify the problem", "Identify the product", "Repeat the request", "Start with the product", "Use official instructions", "Know what is not confirmed", "Choose the right helper", "Summarize the need", "Follow through", "Recognize higher-risk topics", "Separate product facts from professional advice", "Escalate clearly", "CS-103-", "ID", "P01", "P02", "P03", "P04", "P05"], "learning_paths": ["New Retail Employee"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'CS-103 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'CS-103 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'CS-103 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'CS-103 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
commit;
select slug,title,published,
 (select count(*) from public.training_lessons where course_id=c.id) as lessons,
 (select count(*) from public.training_questions where course_id=c.id) as quiz_questions
from public.training_courses c where id='f03c1354-7aec-596c-b72e-7df51d92be50';
